function find(s){return exact.get(s)||folded.get(s.toLocaleLowerCase('ru-RU'));}
function translate(s,lang){const i=languages.indexOf(lang);if(i<0||typeof s!=='string')return s;const composite=s.match(/^Будет создана запланированная карточка:\s*(.*?)\s*•\s*(.*)$/u);if(composite){return translate('Будет создана запланированная карточка:',lang)+' '+translate(composite[1],lang)+' • '+(composite[2]==='у клиента не выбран текущий запрос'||composite[2]==='Запрос без названия'?translate(composite[2],lang):composite[2]);}const v=find(s);if(v){const out=v[i];return s===s.toLocaleUpperCase('ru-RU')&&/[А-ЯЁ]{3}/.test(s)?out.toLocaleUpperCase(lang):out;}for(const [r,a] of rules)if(r.test(s))return s.replace(r,a[i]);return s;}
window.ZabvenyeWorkspaceI18n=Object.freeze({has:s=>typeof s==='string'&&(!!find(s)||/^Будет создана запланированная карточка:\s*.*?\s*•\s*.*$/u.test(s)||rules.some(([r])=>r.test(s))),translate,count:rows.length});
